entries[273405] = { ["name"] = "Finsterer Handel", ["text"] = "100 Energie\nWirken in 4 sek.\nBeim Erreichen von 100 Energie entfesselt die dunkle Brut ein lästerliches Ritual, das den erlittenen und verursachten Schaden sowie die hervorgerufene Heilung aller Kreaturen, einschließlich der Spielercharaktere, innerhalb von 10 Metern um den Zaubernden 30 Sek. lang um 25% erhöht.\n\nJeder Spielercharakter, der 2 Stapel von ' Finsterer Handel ' erreicht, wird zu einem widerwilligen Diener von G'huun und greift seine Verbündeten an, bis seine Gesundheit auf 50% des maximalen Werts verringert wurde." }
