entries[273714] = { ["name"] = "Gunst der Stunde!", ["text"] = "100 Meter Reichweite\nSofort\nEure Zauber und Fähigkeiten haben eine Chance, Euch für 8 Sek. 'Durchtriebene Intrigen' zu gewähren. Nachdem Ihr 3 verschiedene Zauber eingesetzt habt, wandelt sich dieser Effekt in 'Den Augenblick nutzen!' um, was Euer Tempo für 20 Sek. um 241 erhöht." }
