entries[273845] = { ["name"] = "Kettenblitzschlag", ["text"] = "30 Meter Reichweite\nWirken in 2 sek. 6 sek. Abklingzeit\nTrifft einen Gegner mit einem Blitzschlag, der auf einen weiteren Gegner in der Nähe überspringt. Der Zauber wirkt auf bis zu 3 Ziele und fügt jedem folgenden Ziel immer geringeren Naturschaden zu." }
entries[273846] = { ["name"] = "Totem des heilenden Flusses", ["text"] = "40 Mana\nSofort\nBeschwört ein Totem des heilenden Flusses mit 5 Gesundheit zu Füßen des Zaubernden, das Verbündete in der Nähe alle 2 Sek. um 0 Gesundheit heilt. Hält 1 Min. lang an." }
entries[273847] = { ["name"] = "Heilender Fluss", ["text"] = "Sofort\nBeschwört für 15 Sek. ein Totem zu Euren Füßen, das [ Rauschende Ströme : zwei verletzte Gruppen- oder Schlachtzugsmitglieder / ein verletztes Gruppen- oder Schlachtzugsmitglied] innerhalb von 40 Metern alle 2 Sek. um (67.68% der Zaubermacht) Gesundheit heilt.\n\nWenn Ihr [ Totem des Wolkenbruchs : ' Totem des Wolkenbruchs ' / ' Totem des heilenden Flusses '] bereits erlernt habt, erhaltet Ihr stattdessen 1 zusätzliche Aufladung von [ Totem des Wolkenbruchs : ' Totem des Wolkenbruchs ' / ' Totem des heilenden Flusses ']." }
